source("pre.R")
cat("vctrs:", requireNamespace("vctrs", quietly=TRUE), " tibble:", requireNamespace("tibble", quietly=TRUE), " dplyr:", requireNamespace("dplyr", quietly=TRUE), "\n")
tw <- id_layout("twitter"); dc <- id_layout("discord")
s1 <- id_parse(c("9","10","1541815603606036480","100"), "snowflake", layout=tw)
if (requireNamespace("vctrs", quietly=TRUE)) { library(vctrs)
p("vec_c", vec_c(s1, s1[1])); p("vec_c chr", class(vec_c(s1, "77"))); p("vec_c chr first", class(vec_c("77", s1)))
p("vec_c diff layout", vec_c(s1, id_parse("9","snowflake",layout=dc)))
a <- sqids(c(1,2)); b <- sqids(c(1,2), alphabet="zyxwvutsrqponmlkjihgfedcba")
p("vec_c diff alphabets", {z <- vec_c(a, b); print(z); id_fields(z)$numbers})
p("c diff alphabets", c(a, b))
p("vec_c min_length", {z <- vec_c(sqids(1), sqids(1, min_length=10)); print(z); print(attributes(z)); id_valid(z, "sqids")})
p("vec_c nanoid alph", {z <- vec_c(nanoid(1), nanoid(1, alphabet="ab")); attributes(z)$alphabet})
p("vec_c uuid ulid", vec_c(uuid(1), ulid(1)))
p("vec_sort", as.character(vec_sort(s1))); p("vec_order", vec_order(s1)); p("base order", order(s1))
p("vec_unique", vec_unique(vec_c(s1,s1))); p("vec_slice", vec_slice(s1, 2:3)); p("vec_assign chr", {y <- s1; vec_slice(y, 1) <- "5"; y}); p("vec_assign bad", {y <- s1; vec_slice(y, 1) <- "005"; y})
p("vec_cast chr->zuid", vec_cast("77", s1)); p("vec_cast zuid->chr", vec_cast(s1, character())); p("vec_cast across layouts", attr(vec_cast(id_parse("9","snowflake",layout=dc), s1), "layout")$name)
p("vec_rbind", {d <- vec_rbind(data.frame(id=s1[1]), data.frame(id=s1[2])); class(d$id)}); p("vec_ptype_abbr", vec_ptype_abbr(s1)); p("vec_init", vec_init(s1, 2)); p("vec_equal", vec_equal(s1, s1)); p("vec_names", vec_c(a = s1[1], b = s1[2]))
p("vec_match", vec_match("9", s1)); p("vec_in", vec_in(s1, "9"))
if (requireNamespace("tibble", quietly=TRUE)) { p("tibble", tibble::tibble(id = s1)) }
if (requireNamespace("dplyr", quietly=TRUE)) { p("arrange", as.character(dplyr::arrange(tibble::tibble(id = s1), id)$id)); p("bind_rows", class(dplyr::bind_rows(tibble::tibble(id = s1), tibble::tibble(id = s1))$id)); p("if_else", class(dplyr::if_else(c(TRUE,FALSE,TRUE,FALSE), s1, s1)));  p("distinct", nrow(dplyr::distinct(tibble::tibble(id=vec_c(s1,s1)))))
 p("arrange uuid/ksuid", {k <- ksuid(1, time=c(1.5e12)); k2 <- c(k, ksuid(3)); identical(as.character(dplyr::arrange(tibble::tibble(id=k2), id)$id), as.character(sort(k2)))}) }
}
# sqids params
a <- sqids(c(5, 10), alphabet="zyxwvutsrqponmlkjihgfedcba", min_length=8, blocklist=c("abc", NA, "XYZ"))
p("sqids attrs", attributes(a)); p("fields", id_fields(a)$numbers); p("valid own", id_valid(a, "sqids")); p("valid as text default", id_valid(as.character(a), "sqids")); p("valid text+params", id_valid(as.character(a), "sqids", alphabet="zyxwvutsrqponmlkjihgfedcba", min_length=8))
p("reparse zuid", identical(id_parse(a), a)); p("reparse zuid min_length=0 explicit", id_parse(a, min_length=0)); p("c text", c(a, as.character(a)[1])); p("a == text", a == as.character(a))
p("blocklist empty vs NULL", {x <- sqids(1, blocklist=character()); y <- sqids(1); t(c(x, y))})
p("blocklist effect", {x <- sqids(c(1:3)); bl <- substr(as.character(x)[2],1,3); y <- sqids(1:3, blocklist=bl); print(rbind(as.character(x), as.character(y))); print(id_fields(y)$numbers); print(id_valid(as.character(y), "sqids")); id_parse(as.character(y), "sqids")})
p("blocklist upper", {y <- sqids(1:3, blocklist=toupper(as.character(sqids(2)))); as.character(y)})
p("alphabet dup", sqids(1, alphabet="aabc")); p("alphabet short", sqids(1, alphabet="ab")); p("alphabet space", sqids(1, alphabet="ab c")); p("alphabet utf8", sqids(1, alphabet="abcé")); p("alphabet NA", sqids(1, alphabet=NA_character_)); p("alphabet 2", sqids(1, alphabet=c("abc","def")))
p("min_length 255", nchar(sqids(1, min_length=255))); p("256", sqids(1, min_length=256)); p("-1", sqids(1, min_length=-1)); p("1.5", sqids(1, min_length=1.5)); p("NA", sqids(1, min_length=NA)); p("chr", sqids(1, min_length="3")); p("c(1,2)", sqids(1, min_length=c(1,2)))
p("numbers -1", sqids(-1)); p("1.5", sqids(1.5)); p("2^53", sqids(2^53)); p("Inf", sqids(Inf)); p("NaN", sqids(NaN)); p("list partial NA", sqids(list(c(1,NA)))); p("list chr", sqids(list("a"))); p("list nested", sqids(list(list(1)))); p("int", sqids(1:3)); p("NULL", sqids(NULL)); p("Date", sqids(Sys.Date())); p("matrix", sqids(matrix(1:4,2)))
p("int list == dbl", identical(as.character(sqids(list(1:3))), as.character(sqids(list(c(1,2,3))))))
p("ref vector [1,2,3]", as.character(sqids(list(c(1,2,3)))))
p("min_length parse arg on nanoid", id_parse("abc", "nanoid", min_length=3)); p("alphabet on uuid", id_valid("x", "uuid", alphabet="abc"))
# nanoid
p("nanoid a", nanoid(2, 5, "a")); p("size 0", nanoid(1, 0)); p("size NA", nanoid(1, NA)); p("size 2.5", nanoid(1, 2.5)); p("nanoid empty alph", nanoid(1, alphabet="")); p("n=0", nanoid(0)); p("alph attr default", attributes(nanoid(1))$alphabet); p("random short", nanoid(1, random=raw(2))); p("random chr", nanoid(1, random="a"))
p("nanoid valid other alph", {x <- nanoid(2, alphabet="ab"); c(id_valid(x, "nanoid"), id_valid(c(x, "abz"), "nanoid", alphabet="ab"), id_valid(c(x,"abz"), "nanoid"))})
p("nanoid c text outside alphabet", {x <- nanoid(1, alphabet="ab"); c(x, "zz")})
p("nanoid size big", nchar(nanoid(1, 65536))); p("nanoid empty string valid", id_valid("", "nanoid")); p("cuid2", id_valid(c("a","ab","1b", strrep("a",32), strrep("a",33), "aB"), "cuid2")); p("cuid2 strict", id_valid(c("ab","1b"), "cuid2", level="strict"))
p("nanoid fields", id_fields(nanoid(1))); p("nanoid time", id_time(nanoid(2))); p("nanoid bytes", id_bytes(nanoid(1))); p("nanoid sort", sort(id_parse(c("b","B","a","_"), "nanoid")))
